"""Shared utility functions for the analysis framework."""

from __future__ import annotations

import time
from collections import defaultdict
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from program_model import ClassDef, MethodSignature, Program


def build_class_index(program: Program) -> dict[str, ClassDef]:
    return {c.name: c for c in program.classes}


def build_method_index(program: Program) -> dict[str, any]:
    index = {}
    for cls in program.classes:
        for method in cls.methods:
            key = method.signature.full_signature()
            index[key] = (cls, method)
    return index


def build_hierarchy(program: Program) -> dict[str, list[str]]:
    children: dict[str, list[str]] = defaultdict(list)
    for cls in program.classes:
        if cls.super_class:
            children[cls.super_class].append(cls.name)
        for iface in cls.interfaces:
            children[iface].append(cls.name)
    return dict(children)


def get_all_subclasses(hierarchy: dict[str, list[str]], class_name: str) -> set[str]:
    result = set()
    worklist = [class_name]
    while worklist:
        current = worklist.pop()
        for child in hierarchy.get(current, []):
            if child not in result:
                result.add(child)
                worklist.append(child)
    return result


class Timer:
    def __init__(self):
        self._start = None
        self._elapsed_ms = 0

    def __enter__(self):
        self._start = time.perf_counter()
        return self

    def __exit__(self, *args):
        self._elapsed_ms = (time.perf_counter() - self._start) * 1000

    @property
    def elapsed_ms(self) -> float:
        return self._elapsed_ms

